import { OpenCitiesCollection, VenuesCollection, type Venue } from '../collections';
import { venueDefinitions, type VenueType } from '/imports/domain/venueTypes';
import { venueKey } from '/imports/domain/recommendations';
import type { Candidate } from '../llm/prompt';
import { cachedRatings, isFresh, ratingFacts, refreshCityRatings } from './googleRatings';

/** Pool size handed to the ranker; it picks the final 20. */
const POOL = 120;
/** Top venues by source confidence that a type's share is sampled from. */
const SHORTLIST_PER_TYPE = 400;
/** Share of a type's pool drawn from the exact kinds the person saved. */
const PREFERRED_SHARE = 0.7;

const NIGHT: VenueType[] = ['bar', 'club'];

/** The Verger type is stored on each venue at import, so this is an indexed equality. */
function typeFilter(type: VenueType) {
  return { vtype: type };
}

function shuffle<T>(items: T[]): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

/**
 * Discovery without an LLM or web search: every candidate is a real venue
 * from the base, so nothing has to be verified against Google afterwards.
 *
 * The base has no ratings, so the pool leans on what signals it does have:
 * chains are left out, venues both open maps know come first, then those with
 * their own website, and most of
 * each type's share is drawn from the kinds the person saved (cocktail bars
 * for someone who saved cocktail bars, not every pub). Sampling keeps repeat
 * searches from showing the same venues. With a Google key, venues Google
 * rates come first, best rated with the most reviews, and the ranker sees the
 * rating as a fact.
 */
export async function venueCandidates(
  cityPlaceId: string | undefined,
  city: string,
  allowedTypes: VenueType[],
  excludedNames: string[],
  preferredPrimaryTypes: string[] = [],
): Promise<Candidate[]> {
  const openCity = cityPlaceId ? await OpenCitiesCollection.findOneAsync({ placeId: cityPlaceId }) : null;
  const cityName = openCity?.city ?? city.split(',')[0].trim();
  const excluded = new Set(excludedNames.map(venueKey));
  const share = Math.max(10, Math.ceil(POOL / Math.max(1, allowedTypes.length)));
  const pool: Candidate[] = [];
  const kinds = preferredPrimaryTypes.length ? preferredPrimaryTypes
    : allowedTypes.flatMap(type => [...venueDefinitions[type].googleTypes as readonly string[]]);
  await refreshCityRatings(cityName, kinds).catch(() => undefined);
  type Rated = Venue & { rating?: number; ratingCount?: number; ratingAt?: Date };
  const strength = (venue: Rated) => isFresh(venue.ratingAt) && venue.rating
    ? venue.rating * Math.log10((venue.ratingCount ?? 0) + 10) : 0;
  const shortlist = async (filter: object) => {
    const query = { city: cityName, candidate: true, chain: { $ne: true }, ...filter };
    const fields = { venueId: 1, name: 1, primaryType: 1, website: 1, attested: 1 };
    // Found in both open maps first: two independent sources are the best sign
    // of a real, noticed venue the base has without ratings.
    const attested: Venue[] = await VenuesCollection.find({ ...query, attested: true },
      { sort: { confidence: -1 }, limit: SHORTLIST_PER_TYPE, fields }).fetchAsync();
    const single: Venue[] = attested.length >= SHORTLIST_PER_TYPE ? [] : await VenuesCollection.find(
      { ...query, attested: false },
      { sort: { confidence: -1 }, limit: SHORTLIST_PER_TYPE - attested.length, fields }).fetchAsync();
    const found = [...attested, ...single];
    const ratings = await cachedRatings(found.map(venue => venue.venueId));
    const venues: Rated[] = found.map(venue => ({ ...venue, ...ratings.get(venue.venueId) }));
    const rated = venues.filter(venue => strength(venue) > 0).sort((a, b) => strength(b) - strength(a));
    const rest = venues.filter(venue => strength(venue) === 0);
    const both = (venue: Venue) => venue.attested === true;
    // Within each signal level the order is shuffled so repeat searches differ.
    return [...rated,
      ...shuffle(rest.filter(v => both(v) && v.website)), ...shuffle(rest.filter(v => both(v) && !v.website)),
      ...shuffle(rest.filter(v => !both(v) && v.website)), ...shuffle(rest.filter(v => !both(v) && !v.website))]
      .filter(venue => !excluded.has(venueKey(venue.name)));
  };
  for (const type of allowedTypes) {
    const typeScope = typeFilter(type);
    const preferred = preferredPrimaryTypes.filter(primary =>
      (venueDefinitions[type].googleTypes as readonly string[]).includes(primary) ||
      (type === 'restaurant' && primary.endsWith('_restaurant')));
    const first = preferred.length
      ? (await shortlist({ vtype: type, primaryType: { $in: [...new Set(preferred)] } })).slice(0, Math.ceil(share * PREFERRED_SHARE))
      : [];
    const taken = new Set(first.map(venue => venue.venueId ?? venue.name));
    const rest = (await shortlist(typeScope)).filter(venue => !taken.has(venue.venueId ?? venue.name));
    for (const venue of [...first, ...rest].slice(0, share)) {
      pool.push({
        n: venue.name,
        a: '',
        s: venue.primaryType.replace(/_/g, ' '),
        dn: NIGHT.includes(type) ? 'night' : 'day',
        ...(ratingFacts(venue) ? { facts: ratingFacts(venue) } : {}),
      });
    }
  }
  if (!pool.length) throw new Error('CITY_NOT_IN_VENUE_BASE');
  return pool;
}

