87	      (type === 'restaurant' && primary.endsWith('_restaurant')));
88	    const first = preferred.length
89	      ? (await shortlist({ vtype: type, primaryType: { $in: [...new Set(preferred)] } })).slice(0, Math.ceil(share * PREFERRED_SHARE))
90	      : [];
