import { existsSync, readFileSync, statSync } from 'node:fs';

/**
 * Closed-venue filter (TK-006). Off unless FILTER_CLOSED=1, so the pool is
 * exactly what it was before. A registry's "closed" label alone is not
 * trusted (TK-005: up to 28 of 88 labelled venues were alive); the file named
 * by CLOSED_VENUES_FILE lists only venues where the registry label AND a
 * second source agree (see tools/closed_second_source in the pilot folder,
 * PROTOCOL.md there). One venueId per line, blank and `#` lines ignored.
 */
let cached: { file: string; mtimeMs: number; ids: string[] } | null = null;

export function parseClosedIds(text: string): string[] {
  return [...new Set(text.split(/\r?\n/).map(line => line.trim()).filter(line => line && !line.startsWith('#')))];
}

/** IDs to leave out of the pool; empty when the flag is off or the file is missing. */
export function closedVenueIds(env: Record<string, string | undefined> = process.env): string[] {
  if (env.FILTER_CLOSED !== '1') return [];
  const file = env.CLOSED_VENUES_FILE;
  if (!file || !existsSync(file)) return [];
  const mtimeMs = statSync(file).mtimeMs;
  if (!cached || cached.file !== file || cached.mtimeMs !== mtimeMs) {
    cached = { file, mtimeMs, ids: parseClosedIds(readFileSync(file, 'utf8')) };
  }
  return cached.ids;
}

/** Mongo clause added to the venue query; `{}` when nothing is filtered. */
export function closedScope(ids: string[]): object {
  return ids.length ? { venueId: { $nin: ids } } : {};
}

