import { existsSync, readFileSync, statSync } from 'node:fs';

/**
 * Closed-venue filter (TK-006). Off unless FILTER_CLOSED=1, so the pool is
 * exactly what it was before. A registry's "closed" label alone is not
 * trusted (TK-005: up to 28 of 88 labelled venues were alive); the file named
 * by CLOSED_VENUES_FILE lists only venues where the registry label AND a
 * second source agree (see tools/closed_second_source in the pilot folder,
 * PROTOCOL.md there). One venueId per line, blank and `#` lines ignored.
 */
let cached: { file: string; mtimeMs: number; ids: string[] } | null = null;

export function parseClosedIds(text: string): string[] {
  return [...new Set(text.split(/\r?\n/).map(line => line.trim()).filter(line => line && !line.startsWith('#')))];
}

/** IDs to leave out of the pool; empty when the flag is off or the file is missing. */
export function closedVenueIds(env: Record<string, string | undefined> = process.env): string[] {
  if (env.FILTER_CLOSED !== '1') return [];
  const file = env.CLOSED_VENUES_FILE;
  if (!file || !existsSync(file)) return [];
  const mtimeMs = statSync(file).mtimeMs;
  if (!cached || cached.file !== file || cached.mtimeMs !== mtimeMs) {
    cached = { file, mtimeMs, ids: parseClosedIds(readFileSync(file, 'utf8')) };
  }
  return cached.ids;
}

/** Mongo clause added to the venue query; `{}` when nothing is filtered. */
export function closedScope(ids: string[]): object {
  return ids.length ? { venueId: { $nin: ids } } : {};
}

// Closed-venue filter (TK-006): off by default, pool unchanged. No Meteor, no network.
// Run: node --test scripts/closed-filter.test.mjs
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
function load(path, deps = {}, context = {}) {
  const exports = {};
  const source = readFileSync(new URL('../app/' + path, import.meta.url), 'utf8');
  const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
  runInNewContext(code, { exports, console, ...context, require(id) { assert.ok(id in deps, id); return deps[id]; } });
  return exports;
}

const files = { '/c/closed.txt': '# header\nv2\r\n\nv4\nv2\n' };
const fs = {
  existsSync: p => p in files,
  statSync: () => ({ mtimeMs: 1 }),
  readFileSync: p => files[p],
};
const filter = load('imports/api/places/closedFilter.ts', { 'node:fs': fs });

test('flag off or file missing: nothing is filtered', () => {
  assert.deepEqual(filter.closedVenueIds({ CLOSED_VENUES_FILE: '/c/closed.txt' }), []);
  assert.deepEqual(filter.closedVenueIds({ FILTER_CLOSED: '1' }), []);
  assert.deepEqual(filter.closedVenueIds({ FILTER_CLOSED: '1', CLOSED_VENUES_FILE: '/nope' }), []);
  assert.deepEqual(filter.closedScope([]), {});
});

test('flag on: ids parsed, deduplicated, comments dropped', () => {
  const ids = filter.closedVenueIds({ FILTER_CLOSED: '1', CLOSED_VENUES_FILE: '/c/closed.txt' });
  assert.deepEqual([...ids], ['v2', 'v4']);
  assert.deepEqual(filter.closedScope([...ids]), { venueId: { $nin: ['v2', 'v4'] } });
});

// venueCandidates on a fixed query, with stubbed collections.
const venues = [1, 2, 3, 4, 5, 6].map(n => ({
  venueId: 'v' + n, name: 'Bar ' + n, city: 'Paris', candidate: true, chain: false,
  vtype: 'bar', primaryType: 'bar', attested: n % 2 === 0, confidence: 1 - n / 10,
}));
function setup(env) {
  const queries = [];
  const matches = (doc, q) => Object.entries(q).every(([k, c]) => {
    if (c && typeof c === 'object' && '$ne' in c) return doc[k] !== c.$ne;
    if (c && typeof c === 'object' && '$nin' in c) return !c.$nin.includes(doc[k]);
    return doc[k] === c;
  });
  const Venues = {
    find: (q, o) => ({
      fetchAsync: async () => {
        queries.push(JSON.stringify(q));
        return venues.filter(v => matches(v, q)).sort((a, b) => b.confidence - a.confidence).slice(0, o.limit);
      },
    }),
  };
  const closed = load('imports/api/places/closedFilter.ts', { 'node:fs': fs }, { process: { env } });
  const mod = load('imports/api/places/venueCandidates.ts', {
    '../collections': { OpenCitiesCollection: { findOneAsync: async () => null }, VenuesCollection: Venues },
    '/imports/domain/venueTypes': { venueDefinitions: { bar: { googleTypes: ['bar'] } } },
    '/imports/domain/recommendations': { venueKey: s => s.toLowerCase() },
    './googleRatings': {
      cachedRatings: async () => new Map(), isFresh: () => false, ratingFacts: () => undefined, refreshCityRatings: async () => undefined,
    },
    './closedFilter': closed,
  }, { Math: Object.assign(Object.create(Math), { random: () => 0.5 }) });
  return { run: () => mod.venueCandidates(undefined, 'Paris', ['bar'], []), queries };
}

test('default (flag off): same queries and same pool as before the filter existed', async () => {
  const off = setup({});
  const pool = await off.run();
  assert.deepEqual(off.queries, [
    '{"city":"Paris","candidate":true,"chain":{"$ne":true},"vtype":"bar","attested":true}',
    '{"city":"Paris","candidate":true,"chain":{"$ne":true},"vtype":"bar","attested":false}',
  ]);
  assert.equal(pool.length, 6);
  const emptyList = setup({ FILTER_CLOSED: '1', CLOSED_VENUES_FILE: '/c/empty.txt' });
  assert.deepEqual(await emptyList.run(), pool);
});

test('flag on: closed venues leave the pool, the rest stays', async () => {
  const on = setup({ FILTER_CLOSED: '1', CLOSED_VENUES_FILE: '/c/closed.txt' });
  const names = (await on.run()).map(c => c.n).sort();
  assert.deepEqual(names, ['Bar 1', 'Bar 3', 'Bar 5', 'Bar 6']);
});

