"""TK-006: registry-closed AND second source (OSM) rule. See tk006/PROTOCOL.md. Resumable; writes tk006/DONE last."""
import json, math, os, random, sys, threading, time, urllib.request, urllib.parse
sys.path.insert(0, 'C:/verger-data/pilot')
import tk004_match as M
import tk004_fetch as F
P = 'C:/verger-data/pilot/'
T = P + 'tk006/'
R = P + 'registry/'
os.makedirs(T + 'tiles', exist_ok=True)
SEED = 20261022
URLS = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter',
        'https://overpass.private.coffee/api/interpreter']
UA = {'User-Agent': 'verger-research/1.0 (1993georgiy@gmail.com)', 'Accept': '*/*'}
LIFE = ('disused', 'was', 'abandoned', 'not', 'removed')
NAMEKEYS = ('name', 'brand', 'name:fr', 'alt_name', 'old_name')
LOG = open(T + 'run.log', 'a', encoding='utf8')
def log(*a):
    LOG.write(time.strftime('%H:%M:%S ') + ' '.join(str(x) for x in a) + '\n'); LOG.flush()

def pools():
    ids04 = set()
    for c in ('Paris', 'New_York'):
        ids04 |= {d['venueId'] for d in json.load(open(R + 'sample_%s.json' % c, encoding='utf8'))}
    out = {'Paris': [], 'New York': []}
    for l in open(P + 'venues.ndjson', encoding='utf8'):
        if '"candidate": true' not in l or ('"Paris"' not in l and '"New York"' not in l): continue
        d = json.loads(l)
        if d['candidate'] and d['city'] in out and F.ok(d) and d['venueId'] not in ids04: out[d['city']].append(d)
    for v in out.values(): v.sort(key=lambda d: d['venueId'])
    return out

def paris_fetch(sample):
    path = T + 'fr_raw.jsonl'
    done = {json.loads(l)['venueId'] for l in open(path, encoding='utf8')} if os.path.exists(path) else set()
    B = 'https://recherche-entreprises.api.gouv.fr/'
    with open(path, 'a', encoding='utf8') as f:
        for d in sample:
            if d['venueId'] in done: continue
            q = urllib.parse.quote(d['name'][:80]); out = {'venueId': d['venueId'], 'res': []}
            for e in 'AC':
                time.sleep(.6); out['res'].append(F.get(B + 'search?q=%s&departement=75&section_activite_principale=I&etat_administratif=%s&per_page=25&limite_matching_etablissements=20' % (q, e)))
            for p in (1, 2, 3):
                time.sleep(.6)
                r = F.get(B + 'near_point?lat=%s&long=%s&radius=0.1&section_activite_principale=I&per_page=25&page=%d&limite_matching_etablissements=20' % (d['lat'], d['lng'], p))
                out['res'].append(r)
                if len(r.get('results', [])) < 25: break
            f.write(json.dumps(out, ensure_ascii=False) + '\n'); f.flush()
    log('paris fetch done', len(sample))

def ny_match(venues):
    sla = M.load_sla(); grid = {}
    for x in sla: grid.setdefault((int(x[1] / .005), int(x[2] / .005)), []).append(x)
    rows = []
    for p in venues:
        gi, gj = int(p['lat'] / .005), int(p['lng'] / .005)
        c = [x for di in (-1, 0, 1) for dj in (-1, 0, 1) for x in grid.get((gi + di, gj + dj), []) if abs(x[1] - p['lat']) < .0015 and abs(x[2] - p['lng']) < .0025]
        rows.append({'venueId': p['venueId'], 'name': p['name'], 'lat': p['lat'], 'lng': p['lng'], 'city': 'New York', 'match': M.best(p, c, None)})
    return rows

def paris_match(sample):
    fr = {}
    for l in open(T + 'fr_raw.jsonl', encoding='utf8'):
        r = json.loads(l); fr[r['venueId']] = M.fr_cands(r)
    return [{'venueId': p['venueId'], 'name': p['name'], 'lat': p['lat'], 'lng': p['lng'], 'city': 'Paris',
             'match': M.best(p, fr.get(p['venueId'], []), None)} for p in sample if p['venueId'] in fr]

def closed(rows): return [r for r in rows if r['match'] and not r['match']['any_open']]

TILE = (0.01, 0.015)
def tile_of(p): return (math.floor(p['lat'] / TILE[0]), math.floor(p['lng'] / TILE[1]))
def tile_fetch(key):
    path = T + 'tiles/%d_%d.json' % key
    if os.path.exists(path): return json.load(open(path, encoding='utf8'))
    s, w = key[0] * TILE[0] - .0008, key[1] * TILE[1] - .0008
    n, e = (key[0] + 1) * TILE[0] + .0008, (key[1] + 1) * TILE[1] + .0008
    q = '[out:json][timeout:120];nwr["name"](%s,%s,%s,%s);out tags center bb;' % (s, w, n, e)
    wait = 20
    while True:
        for u in URLS:
            try:
                t0 = time.time()
                j = json.load(urllib.request.urlopen(urllib.request.Request(u, data=urllib.parse.urlencode({'data': q}).encode(), headers=UA), timeout=150))
                els = j['elements']
                json.dump(els, open(path, 'w', encoding='utf8'), ensure_ascii=False)
                log('tile', key, len(els), 'objects', round(time.time() - t0, 1), 's', u.split('/')[2]); time.sleep(3)
                return els
            except Exception as ex: err = str(ex)
        log('tile', key, 'retry in', wait, err[:80]); time.sleep(wait); wait = min(wait * 2, 300)

def dist_m(lat, lng, la, lo):
    x = math.radians(la - lat); y = math.radians(lo - lng) * math.cos(math.radians((lat + la) / 2))
    return 6371000 * math.hypot(x, y)
def dist_el(p, el):
    if 'lat' in el: return dist_m(p['lat'], p['lng'], el['lat'], el['lon'])
    b = el.get('bounds')
    if b:
        la = min(max(p['lat'], b['minlat']), b['maxlat']); lo = min(max(p['lng'], b['minlon']), b['maxlon'])
        return dist_m(p['lat'], p['lng'], la, lo)
    c = el.get('center')
    return dist_m(p['lat'], p['lng'], c['lat'], c['lon']) if c else 1e9

def osm_state(p, els):
    A = M.norm(p['name']); alive = disused = False
    for el in els:
        t = el.get('tags', {})
        sc = max([M.score(A, M.norm(t[k])) for k in NAMEKEYS if t.get(k)], default=0)
        if sc < .75 or dist_el(p, el) > 60: continue
        life = [k for k in t if k.split(':')[0] in LIFE]
        kind = t.get('amenity') or t.get('shop') or t.get('tourism') or t.get('craft') or t.get('office') or ''
        if life: disused = True
        elif kind: alive = True
    return 'alive' if alive else 'disused' if disused else 'none'

def osm_all(pairs):
    out = {}; keys = {}
    for p in pairs: keys.setdefault(tile_of(p), []).append(p)
    for i, (k, ps) in enumerate(sorted(keys.items())):
        els = tile_fetch(k)
        for p in ps: out[p['venueId']] = osm_state(p, els)
        if i % 20 == 0: log('osm tiles', i + 1, '/', len(keys))
    return out

def wilson(k, n, z=1.96):
    if n == 0: return (0, 0)
    p = k / n; den = 1 + z * z / n; c = (p + z * z / 2 / n) / den; h = z * math.sqrt(p * (1 - p) / n + z * z / 4 / n / n) / den
    return (round(c - h, 4), round(c + h, 4))

def main():
    pl = pools(); log('pools', {k: len(v) for k, v in pl.items()})
    paris = random.Random(SEED).sample(pl['Paris'], 400)
    th = threading.Thread(target=paris_fetch, args=(paris,)); th.start()
    # gate: tiles on the 88 TK-005 pairs must reproduce 27/2/59
    pairs05 = json.load(open(P + 'tk005/pairs.json', encoding='utf8'))
    old = json.load(open(P + 'tk005/osm_partial.json', encoding='utf8'))
    def old_state(r):
        h = r['osm']
        if any(not x['lifecycle'] and x['kind'] for x in h): return 'alive'
        return 'disused' if any(x['lifecycle'] for x in h) else 'none'
    g = osm_all(pairs05)
    diff = [(p['venueId'], p['name'], old_state(old[p['venueId']]), g[p['venueId']]) for p in pairs05 if old_state(old[p['venueId']]) != g[p['venueId']]]
    cnt = {s: sum(v == s for v in g.values()) for s in ('alive', 'disused', 'none')}
    json.dump({'tiles_counts_on_88': cnt, 'tk005_counts': {'alive': 27, 'disused': 2, 'none': 59}, 'diff': diff}, open(T + 'gate88.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
    log('gate88', cnt, 'diff', len(diff))
    ny = ny_match(pl['New York']); ny_cl = closed(ny)
    log('NY matched', sum(1 for r in ny if r['match']), 'closed', len(ny_cl), 'of', len(ny))
    st = osm_all(ny_cl)
    th.join(); pr = paris_match(paris); pr_cl = closed(pr); st.update(osm_all(pr_cl))
    drop = {'New York': [r for r in ny_cl if st[r['venueId']] != 'alive'], 'Paris': [r for r in pr_cl if st[r['venueId']] != 'alive']}
    s05 = {x['venueId'] for x in pairs05}
    summ = {'seed': SEED, 'gate88': {'tiles': cnt, 'tk005': {'alive': 27, 'disused': 2, 'none': 59}, 'diff': len(diff)}}
    for c, rows, cl in (('New York', ny, ny_cl), ('Paris', pr, pr_cl)):
        m = sum(1 for r in rows if r['match']); d = len(drop[c])
        summ[c] = {'population': len(rows), 'matched': m, 'registry_closed': len(cl), 'osm': {s: sum(st[r['venueId']] == s for r in cl) for s in ('alive', 'disused', 'none')},
                   'dropped': d, 'dropped_share_of_population': round(d / len(rows), 4), 'wilson': wilson(d, len(rows))}
    summ['Paris']['pool'] = len(pl['Paris']); summ['Paris']['dropped_estimate_on_pool'] = round(summ['Paris']['dropped_share_of_population'] * len(pl['Paris']))
    summ['Paris']['dropped_estimate_range'] = [round(x * len(pl['Paris'])) for x in summ['Paris']['wilson']]
    summ['London'] = {'dropped': 0, 'why': 'FSA lists only active establishments: no closure label'}
    json.dump(summ, open(T + 'summary.json', 'w'), ensure_ascii=False, indent=1)
    with open(T + 'closed_confirmed.txt', 'w', encoding='utf8') as f:
        f.write('# TK-006: registry closed AND OSM disused/none. NY: whole city; Paris: sample of 400 only.\n')
        for c in ('New York', 'Paris'):
            for r in sorted(drop[c], key=lambda r: r['venueId']): f.write(r['venueId'] + '\n')
    pick = []
    for c in ('Paris', 'New York'):
        lst = sorted([r for r in drop[c] if r['venueId'] not in s05], key=lambda r: r['venueId'])
        pick.append(random.Random(SEED).sample(lst, min(20, len(lst))))
    short = 40 - len(pick[0]) - len(pick[1])
    if short > 0:
        rest = [r for r in sorted(drop['New York'], key=lambda r: r['venueId']) if r not in pick[1] and r['venueId'] not in s05]
        pick[1] += random.Random(SEED + 1).sample(rest, min(short, len(rest)))
    v40 = [{'city': r['city'], 'venueId': r['venueId'], 'name': r['name'], 'lat': r['lat'], 'lng': r['lng'], 'registry': r['match']['rname'], 'ref': r['match']['ref'], 'osm': st[r['venueId']]} for grp in pick for r in grp]
    json.dump(v40, open(T + 'verify_40.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
    open(T + 'DONE', 'w').write('ok %s\n' % time.strftime('%H:%M'))
    log('DONE', json.dumps(summ)[:400])

if __name__ == '__main__':
    main()

